const stats = $('Fetch Affiliate Data').all().map(i=>i.json);
const affiliates = $('Fetch Affiliate List').all().map(i=>i.json);

const affiliateMap = {};
affiliates.forEach(a => {
  affiliateMap[a['Affiliate ID']] = { name: a['Name'], email: a['Email'], commission_rate: parseFloat(a['Commission %']||10) };
});

const performance = {};
stats.forEach(row => {
  const id = row['Affiliate ID'];
  const info = affiliateMap[id] || { name: 'Unknown', email: '', commission_rate: 10 };
  if (!performance[id]) {
    performance[id] = { id, name: info.name, email: info.email, clicks: 0, conversions: 0, revenue: 0, commission_rate: info.commission_rate };
  }
  performance[id].clicks += parseInt(row['Clicks']||0);
  performance[id].conversions += parseInt(row['Conversions']||0);
  performance[id].revenue += parseFloat(row['Revenue Generated']||0);
});

const results = Object.values(performance).map(p => ({
  ...p,
  conversion_rate: p.clicks > 0 ? ((p.conversions/p.clicks)*100).toFixed(1) : 0,
  commission_owed: (p.revenue * p.commission_rate / 100).toFixed(2),
  revenue_per_click: p.clicks > 0 ? (p.revenue/p.clicks).toFixed(2) : 0
})).sort((a,b) => b.revenue - a.revenue);

const totalRevenue = results.reduce((s,r)=>s+r.revenue,0);
const totalCommission = results.reduce((s,r)=>s+parseFloat(r.commission_owed),0);

return [{ json: { affiliates: results, total_revenue: totalRevenue.toFixed(2), total_commission: totalCommission.toFixed(2), top_performer: results[0]||null, inactive: results.filter(r=>r.clicks===0) } }];

